import logging
import os
import json


def get_cm_source_build(update_path=None, customer_name=None, configuration_id=None, uuf_build=None):
    """
    Get source build for customer and configuration
    :param customer_name: customer name. if not provided, it will be fetched from CM_TAGS env variable.
    :param configuration_id: configuration id. if not provided, it will be fetched from CM_TAGS env variable.
    :param update_path: update path. if not provided, it will be fetched from CM_TAGS env variable.
    :param uuf_build: uuf build. if not provided, it will be fetched from CM_TAGS env variable.
    :return: source build
    """
    cm_tags = get_cm_uuf_tags()
    if customer_name is None:
        customer_name = cm_tags['UUF_CUSTOMER']
    if configuration_id is None:
        configuration_id = cm_tags['UUF_CONFIGURATION']
    if update_path is None:
        update_path = cm_tags['UPDATE_PATH']
    if uuf_build is None:
        uuf_build = cm_tags['UUF_BUILD']

    if customer_name and configuration_id:
        logging.debug("Getting source build for customer: {} and configuration: {}".format(customer_name,
                                                                                           configuration_id))
        return get_cm_source_build_for_customer(customer_name, configuration_id)
    elif update_path:
        logging.debug("Getting source build for update path: {}".format(update_path))
        return get_cm_default_upgrade_paths().get(update_path)
    elif uuf_build:
        logging.debug("Build from UUF_BUILD: {} tag".format(uuf_build))
        return uuf_build


def get_cm_target_build():
    build_artifacts = get_cm_build_artifacts()
    if build_artifacts:
        return build_artifacts.get('name')


def get_cm_source_build_for_customer(customer_name, configuration_id):
    """
    Get source build for customer and configuration
    """

    build_artifacts = get_cm_build_artifacts()
    if build_artifacts:
        try:
            customer_deployments = build_artifacts['properties']['upgrade_path']['customer_deployments']
            return _get_cm_source_build_for_customer(customer_deployments, customer_name, configuration_id)
        except KeyError:
            logging.debug("No 'customer_deployments' found in build artifacts: {}".format(build_artifacts))


def _get_cm_source_build_for_customer(customer_deployments, customer_name, configuration_id):
    for record in customer_deployments:
        if record['customer'].lower() == customer_name.lower():
            for deployment in record['deployments']:
                if int(deployment['uuf_configuration_id']) == int(configuration_id):
                    return deployment['source_sw_build']


def get_cm_default_upgrade_paths():
    """
    Get default upgrade paths
    :return: default upgrade paths eg
                        {
                            "n2": "SBTS23R4_ENB_0000_000861_000030",
                            "n3": "SBTS23R3_ENB_0000_001271_000000",
                            "n1": "SBTS24R1_ENB_0000_000861_000010",
                            "n0": "SBTS24R2_ENB_0000_000001_000012"
                        },
    """
    build_artifacts = get_cm_build_artifacts()
    if build_artifacts:
        try:
            return build_artifacts['properties']['upgrade_path']['product_defaults']
        except KeyError:
            logging.debug("No default upgrade paths found in build artifacts: {}".format(build_artifacts))


def get_cm_uuf_tags():
    cm_tags = get_cm_tags()
    uuf_tag_names = ['UUF_CUSTOMER', 'UUF_CONFIGURATION', 'UPDATE_PATH', 'UUF_BUILD']
    uuf_tags = {}
    for tag_name in uuf_tag_names:
        uuf_tags[tag_name] = _get_tag_value(tag_name, cm_tags)
    return uuf_tags


def get_cm_build_artifacts():
    cm_artifacts = get_cm_artifacts()
    for artifact in cm_artifacts:
        if artifact.get("type") == "build":
            return artifact
    logging.debug("No build artifacts found in CM Artifacts. CM_ARTIFACTS: {}".format(cm_artifacts))
    return {}


def get_cm_artifacts():
    return json.loads(os.getenv("CM_ARTIFACTS", "[]"))


def get_cm_tags():
    return json.loads(os.getenv("CM_TAGS", "[]"))


def _get_tag_value(tag_name, tag_list):
    if tag_list:
        tag = [tag.split("=")[1] for tag in tag_list if tag_name.lower() in tag.lower()]
        if tag:
            return tag[0]
